package com.library.server.service.impl; import com.library.common.model.PageResult; import com.library.pojo.entity.Reader; import com.library.server.mapper.ReaderMapper; import com.library.server.service.ReaderService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class ReaderServiceImpl implements ReaderService { private final ReaderMapper mapper; private final PasswordEncoder encoder; public ReaderServiceImpl(ReaderMapper mapper,PasswordEncoder encoder){this.mapper=mapper;this.encoder=encoder;} public PageResult<Reader> page(String k,int p,int s){return new PageResult<>(mapper.count(k),p,s,mapper.page(k,(p-1)*s,s));} public Reader get(Long id){return mapper.findById(id);} public void save(Reader x){if(x.getPassword()!=null)x.setPassword(encoder.encode(x.getPassword()));if(x.getMaxBorrow()==null)x.setMaxBorrow(5);mapper.insert(x);} public void update(Reader x){if(x.getPassword()!=null&&!x.getPassword().isBlank())x.setPassword(encoder.encode(x.getPassword()));mapper.update(x);} public void delete(Long id){mapper.delete(id);} }
